const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Cambodia'))
    .geometry();

  const laos = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Laos'))
    .geometry();

  const date = '2018-02-03';

  // 2. Data Acquisition & Check
  // Using MODIS Thermal Anomalies/Fire Daily product
  const fireCol = ee.ImageCollection('MODIS/061/MCD14DL')
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  const colSize = fireCol.size().getInfo();
  console.log(`Fire images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No fire detection data for 2018-02-03.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Count fire detections
  const fireImg = fireCol.mosaic();

  // MaxFRP band or FireMask band - use FireMask (values: 0-9, where 7-9 are fires)
  // Actually MCD14DL has MaxFRP, but let's check available bands
  // MCD14DL has: MaxFRP (fire radiative power), sample (number of fire pixels)
  // We'll use MaxFRP > 0 to indicate fire presence

  const fireMask = fireImg.select('MaxFRP').gt(0);

  // Count fires in Cambodia
  const cambodiaStats = fireMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 1000,
    maxPixels: 1e9
  });

  const cambodiaFires = cambodiaStats.get('MaxFRP').getInfo();

  // Count fires in Laos
  const laosStats = fireMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: laos,
    scale: 1000,
    maxPixels: 1e9
  });

  const laosFires = laosStats.get('MaxFRP').getInfo();

  // 4. Validation & Final Answer
  console.log(`Cambodia fire detections: ${cambodiaFires}`);
  console.log(`Laos fire detections: ${laosFires}`);

  if (cambodiaFires === null || laosFires === null) {
    console.log('Calculation failed - null result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(cambodiaFires) || isNaN(laosFires)) {
    console.log('Calculation failed - NaN result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Valid results - compare
  if (cambodiaFires > laosFires) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
